<script setup lang="ts">
import {Head,Link,useForm} from '@inertiajs/vue3'; import EmptyState from '../../Components/Feedback/EmptyState.vue'; import Pagination from '../../Components/Navigation/Pagination.vue'; import AppLayout from '../../Layouts/AppLayout.vue'; import { useStoreDateTime } from '../../composables/useStoreDateTime';
interface Row{id:number;first_name:string|null;last_name:string|null;email:string|null;phone:string|null;state:string|null;verified_email:boolean;orders_count:number;total_spent:string;updated_at_shopify:string|null;synced_at:string|null} interface P<T>{data:T[];links:Array<{url:string|null;label:string;active:boolean}>} const props=defineProps<{customers:P<Row>;filters:{search?:string;state?:string}}>(); const form=useForm({search:props.filters.search??'',state:props.filters.state??''}); const submit=()=>form.get('/customers',{preserveState:true,replace:true}); const name=(c:Row)=>`${c.first_name??''} ${c.last_name??''}`.trim()||'未命名客户'; const { formatDateTime: date } = useStoreDateTime();
const stateLabel=(value:string|null)=>({enabled:'启用',disabled:'禁用',invited:'已邀请',declined:'已拒绝'}[value??'']??value??'未知'); const money=(value:string)=>Number(value).toFixed(2);
</script>
<template><Head title="客户管理"/><AppLayout :breadcrumbs="[{label:'工作台',href:'/dashboard'},{label:'业务中心'},{label:'客户管理'}]"><div class="mx-auto max-w-7xl space-y-6"><header><p class="text-sm font-semibold text-emerald-700">Shopify 客户</p><h1 class="mt-1 text-3xl font-semibold text-slate-950">客户管理</h1><p class="mt-2 text-sm text-slate-500">查看当前店铺同步的客户资料和消费概况。</p></header><form class="grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:grid-cols-[minmax(0,1fr)_180px_auto]" @submit.prevent="submit"><input v-model="form.search" class="rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm" placeholder="搜索姓名、邮箱或电话"/><select v-model="form.state" class="rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm"><option value="">全部状态</option><option value="enabled">启用</option><option value="disabled">禁用</option><option value="invited">已邀请</option></select><button class="rounded-xl bg-slate-950 px-5 py-2.5 text-sm font-semibold text-white">筛选</button></form><section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div v-if="customers.data.length" class="overflow-x-auto"><table class="w-full min-w-[920px] text-left text-sm"><thead class="border-b border-slate-200 bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-4">客户</th><th class="px-5 py-4">电话</th><th class="px-5 py-4">状态</th><th class="px-5 py-4">订单</th><th class="px-5 py-4">累计消费</th><th class="px-5 py-4">最近更新</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="customer in customers.data" :key="customer.id" class="hover:bg-slate-50"><td class="px-5 py-4"><Link :href="`/customers/${customer.id}`" class="font-semibold text-slate-950 hover:text-emerald-700">{{name(customer)}}</Link><p class="mt-1 text-xs text-slate-400">{{customer.email||'无邮箱'}}</p></td><td class="px-5 py-4 text-slate-600">{{customer.phone||'—'}}</td><td class="px-5 py-4"><span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold text-slate-600">{{stateLabel(customer.state)}}</span></td><td class="px-5 py-4">{{customer.orders_count}}</td><td class="px-5 py-4 font-semibold">{{money(customer.total_spent)}}</td><td class="px-5 py-4 text-xs text-slate-500">{{date(customer.updated_at_shopify)}}</td></tr></tbody></table></div><EmptyState v-else class="border-0 shadow-none" title="暂无客户数据" description="创建客户同步任务后，Shopify 客户会显示在这里。" icon="customers"/></section><Pagination :links="customers.links"/></div></AppLayout></template>
